TLM.f("Sancti/06-18",{"officium":"S. Ephræm Syri Confessoris et Ecclesiæ Doctorem","rule":["vide C5a;","Gloria","CredoDA"],"fallback":"Commune/C5a","from":{"Introitus":"Commune/C5a","Lectio":"Commune/C5a","Graduale":"Commune/C5a","GradualeP":"Commune/C5a","Tractus":"Commune/C5a","Evangelium":"Commune/C5a","Offertorium":"Commune/C5a","Communio":"Commune/C5a"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 15:5"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui Ecclésiam tuam beáti Ephræm Confessóris tui et Doctoris mira eruditióne et præcláris vitæ méritis illustráre voluísti: te súpplices exorámus; ut, ipso intercedénte, eam advérsus erróris et pravitátis insídias perénni tua virtúte deféndas."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"2 Tim 4:1-8"},{"k":"text","la":"Caríssime: Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: prǽdica verbum, insta opportúne, importúne: árgue, óbsecra, íncrepa in omni patiéntia, et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria, coacervábunt sibi magístros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum imple. Sóbrius esto. Ego enim jam delíbor, et tempus resolutiónis meæ instat. Bonum certámen certávi, cursum consummávi, fidem servávi. In réliquo repósita est mihi coróna justítiæ, quam reddet mihi Dóminus in illa die, justus judex: non solum autem mihi, sed et iis, qui díligunt advéntum ejus."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum."},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:13-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus, qui in domo sunt. Sic luceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum."}],"Offertorium":[{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus, quæ in Líbano est, multiplicábitur. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sancti Ephræm Confessóris tui atque Doctóris nobis, Dómine, pia non desit orátio: quæ et múnera nostra concíliet; et tuam nobis indulgéntiam semper obtíneat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Ut nobis, Dómine, tua sacrifícia dent salútem: beátus Ephræm Conféssor tuus et Doctor egrégius, quǽsumus, precátor accédat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"f17bbac22be741ea":{"t":"Sir 15, 5, Ps 91, 2\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave. (Ps. 91, 2) Dobro je slaviti Gospodina i pjevati imenu tvojem, Višnji!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave."},"90d80e395c2d5989":{"t":"<i>Pomolimo se</i>.\nBože, koji si htio svoju Crkvu prosvijetliti divnom učenošću i slavnim zaslugama života blaženog Efrema, priznavaoca svog i naučitelja. ponizno te molimo, da je po njegovu zagovoru čuvaš svojom neprolaznom jakošću protiv spletaka zablude i zloće.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c97d830457c280ab":{"t":"2 Tim 4, 1-8\nČitanje Poslanice bl. Pavla apostola Timoteju. Predragi, zaklinjem te pred Bogom i Isusom Kristom koji će suditi žive i mrtve njegovim dolaskom i njegovim kraljevstvom, propovijedaj riječ, revnuj u zgodno i nezgodno vrijeme, karaj, moli, opominji sa svom strpljivošću i naukom. Jer će doći vrijeme kad neće primati zdrave nauke, nego će oko sebe skupiti naučitelje po svojim požudama koji će im ugađati ušima. Odvraćat će uši od istine, a obraćat će ih k bajkama. Ali ti bdij, budi u svemu strpljiv, izvršuj djelo evanđeliste, ispunjavaj svoju službu. Budi trijezan! Ja sam već žrtvovan i vrlo je blizu vrijeme moje smrti. Dobar sam boj bio, tijek svršio, vjeru održao. Na kraju mi je pripravljen vijenac pravde koji će mi u onaj dan dati Gospodin, pravedni sudac, ali ne samo meni, nego i onima koji ljube njegov dolazak."},"043b43931c3a674e":{"t":"Ps 36, 30-31\nPravednikova usta raspravljaju o mudrosti i njegov jezik govori o pravdi. Zakon mu je Božji u srcu, i noge mu neće posrnuti.\n\nSir 45, 9\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodin ga je ljubio i ukrasio, zaodjenuo ga je haljinom slave. <i>Aleluja</i>."},"a220bcd1476c8c48":{"t":"Mt 5, 13-19\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Vi ste sol zemlje. Ako sol izvjetri, čim će se soliti? Za ništa više ne vrijedi, nego da se izbaci i da je ljudi pogaze. Vi ste svjetlo svijeta. Ne može se sakriti grad sazidan na gori. Niti se upaljuje svijeća i postavlja pod varićak, nego na svijećnjak da svijetli svima koji su u kući. Tako neka svijetli vaše svjetlo pred ljudima da vide vaša dobra djela i slave vašega nebeskog Oca. Nemojte misliti da sam došao ukinuti zakon ili proroke! Nisam došao ukinuti nego dopuniti. Zaista vam kažem, dok stoji nebo i zemlja, neće od zakona nestati ni jednog slova, niti jednog znaka, dok se sve ne ispuni. Tko, dakle, dokine jednu od ovih najmanjih zapovijedi i tako nauči ljude, bit će najmanji u kraljevstvu nebeskom. A tko bude vršio i naučavao, taj će biti velik u kraljevstvu nebeskom."},"26bc9b7e0a4c66c8":{"t":"Ps 91, 13\nPravednik cvate kao palma i raste kao libanski cedar."},"2888a5d6b8e7b880":{"t":"Neka nam, Gospodine, pomogne pobožna molitva svetoga Efrema tvoga priznavaoca i naučitelja, i neka njegova molitva učini da ti naši darovi budu prijatni i isprosi nam oproštenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"43352d99b4b928c1":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada."},"f974ca69a6fcbd58":{"t":"<i>Pomolimo se</i>.\nNeka se zauzme za nas, molimo, Gospodine, blaženi Efrem, tvoj priznavalac i naučitelj, da nam tvoje žrtve donesu spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timotheum"},{"k":"ref","la":"2 Tim 4:1-8"},{"k":"text","la":"Caríssime: Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: praedica verbum, insta opportúne, importune: árgue, óbsecra, íncrepa in omni patiéntia, et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria, coacervábunt sibi magistros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum ímple. Sóbrius esto. Ego enim jam delíbor, et tempus resolutiónis meæ instat. Bonum certámen certávi, cursum consummávi, fidem servávi. In réliquo repósita est mihi coróna justítiæ, quam reddet mihi Dóminus in illa die, justus judex: non solum autem mihi, sed et iis, qui díligunt advéntum ejus."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum."},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:13-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus qui in domo sunt. Sic lúceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in coelis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat coelum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno coelórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno coelórum."}],"Offertorium":[{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus, quæ in Líbano est multiplicábitur. (Allelúja.)"}]}}});
